def bind(path):
    p=Path(path);b=p.read_bytes()
    return {'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
def load(path):return json.loads(Path(path).read_text())
def verify(row):
    current=bind(row['path'])
    assert all(row[k]==current[k] for k in ('bytes','sha256')),(row,current)
    return current
def write(name,value):
    with (HERE/name).open('x') as s:s.write(json.dumps(value,indent=2,ensure_ascii=False)+'\n')
def normalize(text):return ' '.join(text.split())

class Node:
    def __init__(self,tag,attrs=(),parent=None):
        self.tag=tag;self.attrs=dict(attrs);self.parent=parent;self.children=[]
    def text(self):return ''.join(x if isinstance(x,str) else x.text() for x in self.children)
    def elements(self):return [x for x in self.children if isinstance(x,Node)]
    def signature(self):
        children=[]
        for child in self.children:
            if isinstance(child,str):
                if normalize(child):children.append(['text',normalize(child)])
            else:children.append(child.signature())
        return [self.tag,sorted(self.attrs.items()),children]

class DOM(HTMLParser):
    VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def __init__(self,text):
        super().__init__(convert_charrefs=True)
        self.root=Node('root');self.stack=[self.root];self.nodes=[];self.feed(text);self.close()
        assert len(self.stack)==1,[(x.tag,x.attrs) for x in self.stack]
    def handle_starttag(self,tag,attrs):
        node=Node(tag,attrs,self.stack[-1]);self.stack[-1].children.append(node);self.nodes.append(node)
        if tag not in self.VOID:self.stack.append(node)
    def handle_startendtag(self,tag,attrs):
        node=Node(tag,attrs,self.stack[-1]);self.stack[-1].children.append(node);self.nodes.append(node)
    def handle_endtag(self,tag):
        assert self.stack[-1].tag==tag,(self.stack[-1].tag,tag)
        self.stack.pop()
    def handle_data(self,data):
        kids=self.stack[-1].children
        if kids and isinstance(kids[-1],str):kids[-1]+=data
        else:kids.append(data)

_FORMAT=re.compile(r'(</?(?:sup|sub|i|em)>)',re.IGNORECASE)
def expected_label(value):
